    /// <summary>A new icon each time: a XAML element can only be in one place.</summary>
    public static PathIcon Create(TimerPhase phase) => new()
    {
        Data = (Geometry)XamlBindingHelper.ConvertValue(typeof(Geometry), phase switch
        {
            TimerPhase.ShortBreak => DrinkCoffee,
            TimerPhase.LongBreak => Bed,
            _ => BrainCircuit,
        }),
    };
